+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+
+const session: ChatSession = {
+  sessionId: 'test-session',
+  userId: 'user-1',
+  entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
+};
+
+const provider: AIProvider = {
+  // eslint-disable-next-line require-yield
+  async *sendMessage(): AsyncGenerator<MessageChunk> {
+    throw undefined;
+  },
+  async generateStructured<T>(): Promise<T> {
+    return {} as T;
+  },
+};
+
+it('wraps an undefined rejection for onError while preserving its cause and caller value', async () => {
+  let observed: Error | undefined;
+  const hooks: OrchestratorHooks = {
+    onError: async (_session, error) => {
+      observed = error;
+    },
+  };
+  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test assistant'}), undefined, {
+    hooks,
+  });
+
+  const outcome = await orchestrator.processMessage(session).then(
+    value => ({rejected: false, value}),
+    reason => ({rejected: true, reason})
+  );
+
+  expect(observed).toBeInstanceOf(Error);
+  expect(observed?.message).toBe('undefined');
+  expect(observed && Object.hasOwn(observed, 'cause')).toBe(true);
+  expect(observed?.cause).toBeUndefined();
+  expect(outcome).toEqual({rejected: true, reason: undefined});
+});
